public void testSplits() {
    Options opts = new Options("foo", WordCountCombiner.class, String.class, Long.class, 3);
    opts.setBucketsPerTablet(1);
    FluoConfiguration fluoConfig = new FluoConfiguration();
    CollisionFreeMap.configure(fluoConfig, opts);
    TableOptimizations tableOptim1 = CollisionFreeMap.getTableOptimizations("foo", fluoConfig.getAppConfiguration());
    List<Bytes> expected1 = Lists.transform(Arrays.asList("foo:d:1", "foo:d:2", "foo:d:~", "foo:u:1", "foo:u:2", "foo:u:~"), Bytes::of);
    Assert.assertEquals(expected1, sort(tableOptim1.getSplits()));
    Options opts2 = new Options("bar", WordCountCombiner.class, String.class, Long.class, 6);
    opts2.setBucketsPerTablet(2);
    CollisionFreeMap.configure(fluoConfig, opts2);
    TableOptimizations tableOptim2 = CollisionFreeMap.getTableOptimizations("bar", fluoConfig.getAppConfiguration());
    List<Bytes> expected2 = Lists.transform(Arrays.asList("bar:d:2", "bar:d:4", "bar:d:~", "bar:u:2", "bar:u:4", "bar:u:~"), Bytes::of);
    Assert.assertEquals(expected2, sort(tableOptim2.getSplits()));
    TableOptimizations tableOptim3 = CollisionFreeMap.getTableOptimizations(fluoConfig.getAppConfiguration());
    ArrayList<Bytes> expected3 = new ArrayList<>(expected2);
    expected3.addAll(expected1);
    Assert.assertEquals(expected3, sort(tableOptim3.getSplits()));
}

@Test
public void testTx() {
    rtx.set(Bytes.of("r1"), new Column("cf1"), Bytes.of("v1"));
    rtx.set(Bytes.of("r2"), new Column("cf2", "cq2"), Bytes.of("v2"));
    rtx.delete(Bytes.of("r3"), new Column("cf3"));
    expect(tx.get(Bytes.of("r4"), new Column("cf4"))).andReturn(Bytes.of("v4"));
    replay(tx);
    rtx.get(Bytes.of("r4"), new Column("cf4"));
    List<LogEntry> entries = rtx.getTxLog().getLogEntries();
    Assert.assertEquals(4, entries.size());
    Assert.assertEquals("LogEntry{op=SET, row=r1, col=cf1  , value=v1}", entries.get(0).toString());
    Assert.assertEquals("LogEntry{op=SET, row=r2, col=cf2 cq2 , value=v2}", entries.get(1).toString());
    Assert.assertEquals("LogEntry{op=DELETE, row=r3, col=cf3  , value=}", entries.get(2).toString());
    Assert.assertEquals("LogEntry{op=GET, row=r4, col=cf4  , value=v4}", entries.get(3).toString());
    Assert.assertEquals("{r4 cf4  =v4}", rtx.getTxLog().getOperationMap(LogEntry.Operation.GET).toString());
    Assert.assertEquals("{r2 cf2 cq2 =v2, r1 cf1  =v1}", rtx.getTxLog().getOperationMap(LogEntry.Operation.SET).toString());
    Assert.assertEquals("{r3 cf3  =}", rtx.getTxLog().getOperationMap(LogEntry.Operation.DELETE).toString());
}

