@Test
public void testFilter() {
    rtx = RecordingTransaction.wrap(tx, le -> le.getColumn().getFamily().toString().equals("cfa"));
    TypedTransaction ttx = tl.wrap(rtx);
    ttx.mutate().row("r1").fam("cfa").qual("cq1").set("1");
