    ColumnIterator colIter = rowEntry.getValue();
    Assert.assertTrue(colIter.hasNext());
    Assert.assertTrue(rtx.getTxLog().isEmpty());
    Map.Entry<Column, Bytes> colEntry = colIter.next();
    Assert.assertFalse(rtx.getTxLog().isEmpty());
